#include <limits>
using namespace std;

using LL = unsigned long long;

int main() {
    LL n, k;
    cin >> n >> k;

    LL d = 0;
    if (k > 0 && k < numeric_limits<LL>::max()) {
        d = (n >> 1) / (k + 1);
    }

    LL c = d * k;
    LL w = n - d - c;

    cout << d << " " << c << " " << w << '\n';
    return 0;
}

